/**
 * The derived XSD inventory of the ASI processing vocabulary: one entry per kind handle, 89
 * entries.
 *
 * Generated by `node src/vocab/derive/derive.ts processing` over `imsqti_asiv3p0p1_v1p0.xsd` and
 * formatted with `vp fmt`; `src/vocab/derive/derive.test.ts` checks that a re-run reproduces this
 * file byte for byte. Attribute declarations by `whiteSpace` class over these entries: collapse 52,
 * preserve 9, replace 1, union 10.
 *
 * A choice group's members each carry the group's bounds multiplied into their own, so a member of
 * a `(a | b){1..n}` group reads `{ min: 1, max: None }`. The choice groups of two to six members,
 * by entry (the larger groups are the flow, inline and block content sets and carry `0..n` or
 * `1..n`):
 *
 * - `qti-outcome-else`: (qti-lookup-outcome-value | qti-outcome-processing-fragment |
 *   qti-set-outcome-value | xi:include | qti-exit-test | qti-outcome-condition){0..n}
 * - `qti-outcome-else-if`: (qti-lookup-outcome-value | qti-outcome-processing-fragment |
 *   qti-set-outcome-value | xi:include | qti-exit-test | qti-outcome-condition){0..n}
 * - `qti-outcome-if`: (qti-lookup-outcome-value | qti-outcome-processing-fragment |
 *   qti-set-outcome-value | xi:include | qti-exit-test | qti-outcome-condition){0..n}
 * - `qti-outcome-processing`: (qti-lookup-outcome-value | qti-outcome-processing-fragment |
 *   qti-set-outcome-value | xi:include | qti-exit-test | qti-outcome-condition){0..n}
 * - `qti-outcome-processing-fragment`: (qti-lookup-outcome-value | qti-outcome-processing-fragment |
 *   qti-set-outcome-value | xi:include | qti-exit-test | qti-outcome-condition){0..n}
 * - `qti-response-else`: (xi:include | qti-response-condition | qti-response-processing-fragment |
 *   qti-set-outcome-value | qti-exit-response | qti-lookup-outcome-value){0..n}
 * - `qti-response-else-if`: (xi:include | qti-response-condition | qti-response-processing-fragment |
 *   qti-set-outcome-value | qti-exit-response | qti-lookup-outcome-value){0..n}
 * - `qti-response-if`: (xi:include | qti-response-condition | qti-response-processing-fragment |
 *   qti-set-outcome-value | qti-exit-response | qti-lookup-outcome-value){0..n}
 * - `qti-response-processing-fragment`: (xi:include | qti-response-condition |
 *   qti-response-processing-fragment | qti-set-outcome-value | qti-exit-response |
 *   qti-lookup-outcome-value){0..n}
 * - `qti-template-else`: (qti-set-template-value | qti-exit-template | qti-template-condition |
 *   qti-set-default-value | qti-set-correct-response | qti-template-constraint){0..n}
 * - `qti-template-else-if`: (qti-set-template-value | qti-exit-template | qti-template-condition |
 *   qti-set-default-value | qti-set-correct-response | qti-template-constraint){0..n}
 * - `qti-template-if`: (qti-set-template-value | qti-exit-template | qti-template-condition |
 *   qti-set-default-value | qti-set-correct-response | qti-template-constraint){0..n}
 * - `qti-template-processing`: (qti-set-template-value | qti-exit-template | qti-template-condition |
 *   qti-set-default-value | qti-set-correct-response | qti-template-constraint){1..n}
 */
import { Option } from "effect";

import type {
  InventoryAttribute,
  InventoryChild,
  InventoryContent,
  InventoryFacetName,
  InventoryInlineType,
  InventoryLeaf,
  InventoryType,
  InventoryValueType,
} from "#pantry/schema/content/xsd-inventory.ts";

/**
 * Build an attribute row from a declaration of a named type.
 *
 * @param name - The attribute name as the XSD spells it.
 * @param type - The declared type's name.
 * @param use - Whether the XSD requires the attribute.
 * @param family - Which attribute family the name belongs to.
 * @param whiteSpace - The `whiteSpace` class of the declared type.
 * @param defaultValue - The XSD `default`, absent when none is declared.
 * @returns The attribute row.
 */
const attribute = (
  name: string,
  type: string,
  use: InventoryAttribute["use"],
  family: InventoryAttribute["family"],
  whiteSpace: InventoryAttribute["whiteSpace"],
  defaultValue?: string,
): InventoryAttribute => ({
  default: Option.fromNullishOr(defaultValue),
  family,
  inline: Option.none(),
  name,
  type,
  use,
  whiteSpace,
});

/**
 * Build a child row from an element reference.
 *
 * @param name - The referenced element name as the XSD spells it.
 * @param min - The effective minimum occurrence.
 * @param max - The effective maximum occurrence, `None` when unbounded.
 * @returns The child row.
 */
const child = (name: string, min: number, max: Option.Option<number>): InventoryChild => ({
  max,
  min,
  name,
});

/**
 * Build an attribute row from a declaration of an anonymous type.
 *
 * @param name - The attribute name as the XSD spells it.
 * @param type - The anonymous type, as one of the leaf's constants holds it.
 * @param use - Whether the XSD requires the attribute.
 * @param family - Which attribute family the name belongs to.
 * @param defaultValue - The XSD `default`, absent when none is declared.
 * @returns The attribute row.
 */
const inlineAttribute = (
  name: string,
  type: InventoryValueType,
  use: InventoryAttribute["use"],
  family: InventoryAttribute["family"],
  defaultValue?: string,
): InventoryAttribute => ({
  ...type,
  default: Option.fromNullishOr(defaultValue),
  family,
  name,
  use,
});

/**
 * Build an anonymous simple type as the rows that declare it read it.
 *
 * @param type - The type's designator: `list`, `union` or its restriction's base.
 * @param whiteSpace - The type's `whiteSpace` class.
 * @param definition - The type's definition.
 * @returns The value type.
 */
const inlineType = (
  type: string,
  whiteSpace: InventoryValueType["whiteSpace"],
  definition: InventoryInlineType,
): InventoryValueType => ({ inline: Option.some(definition), type, whiteSpace });

/**
 * Build an anonymous list type.
 *
 * @param item - The list's item type.
 * @returns The definition.
 */
const list = (item: InventoryType): InventoryInlineType => ({ _tag: "list", item });

/**
 * Refer to a named simple type.
 *
 * @param name - The type's QName, a built-in spelled `xs:`.
 * @returns The reference.
 */
const named = (name: string): InventoryType => ({ _tag: "named", name });

/**
 * Build an anonymous restriction.
 *
 * @param base - The restricted type.
 * @param facets - Its facets in XSD order, each as its name and its value.
 * @returns The definition.
 */
const restriction = (
  base: InventoryType,
  ...facets: readonly (readonly [InventoryFacetName, string])[]
): InventoryInlineType => ({
  _tag: "restriction",
  base,
  facets: facets.map(([facet, value]) => ({ facet, value })),
});

/**
 * Build the content class of a kind whose text is of a named type.
 *
 * @param type - The type's name.
 * @param whiteSpace - The type's `whiteSpace` class.
 * @returns The `text` class.
 */
const text = (type: string, whiteSpace: InventoryValueType["whiteSpace"]): InventoryContent => ({
  _tag: "text",
  inline: Option.none(),
  type,
  whiteSpace,
});

/**
 * Build an anonymous union type.
 *
 * @param members - The member types, in XSD order.
 * @returns The definition.
 */
const union = (...members: readonly InventoryType[]): InventoryInlineType => ({
  _tag: "union",
  members,
});

/**
 * The anonymous type of `min` on `qti-any-n`, which every declaration of the same definition
 * shares.
 */
const minType = inlineType(
  "union",
  "union",
  union(restriction(named("xs:integer")), restriction(named("VariableStringDType"))),
);

